contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOperator) public {
        address oldOperator = c.operator();
        require(newOperator != oldOperator);
        require(newOperator != address(this));
        bool setReverted;
        try c.setOperator(newOperator) { setReverted = false; } catch { setReverted = true; }
        address opAfter = c.operator();
        bool depReverted;
        try c.depositAndStake(0) { depReverted = false; } catch { depReverted = true; }
        bool resReverted;
        try c.setRewardsRecipient(address(1)) { resReverted = false; } catch { resReverted = true; }
        address recAfter = c.rewardsRecipient();
        assert(
            setReverted
            || (opAfter == newOperator
                && depReverted
                && !resReverted
                && recAfter == address(1))
        );
    }
    receive() external payable {}
}

