contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, address newOperator) public payable {
        require(newOwner != address(this));
        require(newOwner != address(0));
        require(newOperator != address(0));

        // Sanity: while we are the owner, the onlyOwner call succeeds and sets the operator.
        c.setOperator(newOperator);
        require(c.operator() == newOperator);

        // Transfer ownership away from this contract.
        c.transferOwnership(newOwner);

        // Now the previous owner (this contract) must be denied access.
        bool reverted;
        try c.setOperator(address(this)) { reverted = false; } catch { reverted = true; }

        // And the new owner must be able to call it (checked by observing state change).
        // We cannot call as newOwner, so instead verify the operator was NOT changed by the reverted call.
        assert(reverted && c.operator() == newOperator);
    }
    receive() external payable {}
}

